    restartSimulationButton.style('transition', 'background-color 0.2s');

    restartSimulationButton.mouseOver(() => restartSimulationButton.style('background-color', '#1a252f'));
    restartSimulationButton.mouseOut(() => restartSimulationButton.style('background-color', '#2d3e50'));
    restartSimulationButton.mousePressed(() => {
      Tone.start();
      initializePhysicsAndParticles();
    });

    let mainSimulationCanvas = await simulationGraphicsContext.createCanvas(simulationCanvasViewportWidth, simulationCanvasViewportHeight);
    mainSimulationCanvas.parent(masterLayoutWrapper);
    mainSimulationCanvas.elt.style.setProperty('width', simulationCanvasViewportWidth + 'px', 'important');
    mainSimulationCanvas.elt.style.setProperty('height', simulationCanvasViewportHeight + 'px', 'important');
    mainSimulationCanvas.elt.style.setProperty('min-width', simulationCanvasViewportWidth + 'px', 'important');
    mainSimulationCanvas.elt.style.setProperty('min-height', simulationCanvasViewportHeight + 'px', 'important');
    mainSimulationCanvas.elt.style.setProperty('max-width', simulationCanvasViewportWidth + 'px', 'important');
    mainSimulationCanvas.elt.style.setProperty('max-height', simulationCanvasViewportHeight + 'px', 'important');
    mainSimulationCanvas.elt.style.setProperty('box-shadow', '0 12px 32px rgba(0,0,0,0.1)', 'important');

    simulationGraphicsContext.pixelDensity(1);

    uraniumNucleusColorComponents = [0, 169, 92, 220];
    excitedNucleusColorComponents = [255, 232, 0, 240];
