    tactilePaperGrainTextureBuffer = simulationGraphicsContext.createGraphics(simulationCanvasViewportWidth, simulationCanvasViewportHeight);
    tactilePaperGrainTextureBuffer.pixelDensity(1);
    tactilePaperGrainTextureBuffer.loadPixels();

    let totalGrainPixelArrayLength = tactilePaperGrainTextureBuffer.width * tactilePaperGrainTextureBuffer.height * 4;
    for (let currentPixelMemoryIndex = 0; currentPixelMemoryIndex < totalGrainPixelArrayLength; currentPixelMemoryIndex += 4) {
      let randomizedStippleLuminosityValue = simulationGraphicsContext.random(255);
      let calculatedNoiseAlphaOpacity = simulationGraphicsContext.random(15, 30);
      tactilePaperGrainTextureBuffer.pixels[currentPixelMemoryIndex] = randomizedStippleLuminosityValue;
      tactilePaperGrainTextureBuffer.pixels[currentPixelMemoryIndex + 1] = randomizedStippleLuminosityValue;
      tactilePaperGrainTextureBuffer.pixels[currentPixelMemoryIndex + 2] = randomizedStippleLuminosityValue;
      tactilePaperGrainTextureBuffer.pixels[currentPixelMemoryIndex + 3] = calculatedNoiseAlphaOpacity;
    }
    tactilePaperGrainTextureBuffer.updatePixels();

    globalHarmonicScalesDictionary = {
      "Japanese Hirajoshi": {
        low: ["D2", "Eb2", "G2", "A2", "Bb2"],
        mid: ["D3", "Eb3", "G3", "A3", "Bb3", "D4", "Eb4"],
