      },
      "Lydian Dream": {
        low: ["C2", "D2", "E2", "F#2", "G2"],
        mid: ["A2", "B2", "C3", "D3", "E3", "F#3", "G3", "A3", "B3"],
        high: ["C4", "D4", "E4", "F#4", "G4", "A4", "B4", "C5", "D5", "E5"]
      },
