        high: ["B3", "C4", "D4", "E4", "F4", "G#4", "A4", "B4", "C5"]
      }
    };

    availableScaleNamesArray = Object.keys(globalHarmonicScalesDictionary);

    for (let scaleIteratorIndex = 0; scaleIteratorIndex < availableScaleNamesArray.length; scaleIteratorIndex++) {
      scaleSelectionDropdown.option(availableScaleNamesArray[scaleIteratorIndex]);
    }

    scaleSelectionDropdown.changed(() => {
      applySelectedHarmonicScaleByName(scaleSelectionDropdown.value());
    });

    applySelectedHarmonicScaleByName(availableScaleNamesArray[0]);

    masterOutputLimiterAudioNode = new Tone.Limiter(-2).toDestination();

    expansiveReactorRoomReverbNode = new Tone.Reverb({ 
      decay: 6.0, 
      preDelay: 0.1, 
      wet: 0.6 
    }).connect(masterOutputLimiterAudioNode);

    granularPingPongDelayAudioNode = new Tone.PingPongDelay("8n", 0.3).connect(expansiveReactorRoomReverbNode);

    expressiveVibratoAudioNode = new Tone.Vibrato({
      frequency: 5.0,
      depth: 0.1
    }).connect(expansiveReactorRoomReverbNode);

    organicViolaBowedInstrument = new Tone.PolySynth(Tone.MonoSynth, {
      maxPolyphony: 8,
      oscillator: { type: "sawtooth" },
      filter: { Q: 2, type: "lowpass", rolloff: -24 },
      envelope: { attack: 0.5, decay: 0.3, sustain: 0.8, release: 2.5 },
      filterEnvelope: { attack: 0.5, decay: 0.3, sustain: 0.8, release: 2.5, baseFrequency: 150, octaves: 2.0 }
    }).connect(expressiveVibratoAudioNode);
    organicViolaBowedInstrument.volume.value = -12;

    organicOboeWindInstrument = new Tone.PolySynth(Tone.FMSynth, {
      maxPolyphony: 8,
      harmonicity: 2.0,
      modulationIndex: 1.5,
      oscillator: { type: "triangle" },
      envelope: { attack: 0.3, decay: 0.2, sustain: 0.9, release: 2.0 },
      modulation: { type: "square" },
      modulationEnvelope: { attack: 0.3, decay: 0.2, sustain: 0.9, release: 2.0 }
    }).connect(granularPingPongDelayAudioNode);
    organicOboeWindInstrument.volume.value = -14;

    organicKotoPluckInstrument = new Tone.PolySynth(Tone.Synth, {
      maxPolyphony: 16,
      oscillator: { type: "fmtriangle", harmonicity: 2.5, modulationIndex: 1.2 },
      envelope: { attack: 0.005, decay: 2.0, sustain: 0.0, release: 1.5 }
    }).connect(expansiveReactorRoomReverbNode);
    organicKotoPluckInstrument.volume.value = -8;

    initializePhysicsAndParticles();
  };

  function initializePhysicsAndParticles() {
    activeSubatomicParticlesRegistry = [];
    scheduledRigidBodyAnnihilationQueue = [];
    scheduledFissionEventSpawningQueue = [];
    ephemeralKineticRippleWavesArray = [];

    globalLastViolaTriggerTimestamp = 0;
    globalLastOboeTriggerTimestamp = 0;
    globalLastKotoTriggerTimestamp = 0;

    quantumFissionPhysicsEngine = planck.World({ gravity: planck.Vec2(0, 0) });

    let reactorContainmentWallMaterialProperties = { density: 0.0, friction: 0.0, restitution: 1.0 };

    let layoutCoordinateBottomYAxis = simulationCanvasViewportHeight * spatialScaleMetersPerPixelRatio;
    let layoutCoordinateTopYAxis = 0;
    let layoutCoordinateLeftXAxis = 0;
    let layoutCoordinateRightXAxis = simulationCanvasViewportWidth * spatialScaleMetersPerPixelRatio;

    let floorStaticColliderRigidBody = quantumFissionPhysicsEngine.createBody();
    floorStaticColliderRigidBody.createFixture(planck.Edge(planck.Vec2(layoutCoordinateLeftXAxis, layoutCoordinateBottomYAxis), planck.Vec2(layoutCoordinateRightXAxis, layoutCoordinateBottomYAxis)), reactorContainmentWallMaterialProperties);

    let ceilingStaticColliderRigidBody = quantumFissionPhysicsEngine.createBody();
    ceilingStaticColliderRigidBody.createFixture(planck.Edge(planck.Vec2(layoutCoordinateLeftXAxis, layoutCoordinateTopYAxis), planck.Vec2(layoutCoordinateRightXAxis, layoutCoordinateTopYAxis)), reactorContainmentWallMaterialProperties);

    let leftWallStaticColliderRigidBody = quantumFissionPhysicsEngine.createBody();
    leftWallStaticColliderRigidBody.createFixture(planck.Edge(planck.Vec2(layoutCoordinateLeftXAxis, layoutCoordinateTopYAxis), planck.Vec2(layoutCoordinateLeftXAxis, layoutCoordinateBottomYAxis)), reactorContainmentWallMaterialProperties);

    let rightWallStaticColliderRigidBody = quantumFissionPhysicsEngine.createBody();
    rightWallStaticColliderRigidBody.createFixture(planck.Edge(planck.Vec2(layoutCoordinateRightXAxis, layoutCoordinateTopYAxis), planck.Vec2(layoutCoordinateRightXAxis, layoutCoordinateBottomYAxis)), reactorContainmentWallMaterialProperties);

    quantumFissionPhysicsEngine.on('begin-contact', processPhysicsCollisionEvents);

    let reactorCoreCenterXCoordinate = simulationCanvasViewportWidth * 0.5;
    let reactorCoreCenterYCoordinate = simulationCanvasViewportHeight * 0.5;
    let heavyNucleusPlacementRadius = 260;

    for (let nucleusDistributionIterator = 0; nucleusDistributionIterator < 40; nucleusDistributionIterator++) {
      let randomizedRadialDistance = simulationGraphicsContext.random(30, heavyNucleusPlacementRadius);
      let randomizedAngularPositionRadians = simulationGraphicsContext.random(mathematicalPiValue * 2);
      let calculatedPlacementXCoordinate = reactorCoreCenterXCoordinate + Math.cos(randomizedAngularPositionRadians) * randomizedRadialDistance;
      let calculatedPlacementYCoordinate = reactorCoreCenterYCoordinate + Math.sin(randomizedAngularPositionRadians) * randomizedRadialDistance;

      instantiateSubatomicParticleEntity(calculatedPlacementXCoordinate, calculatedPlacementYCoordinate, "heavyUraniumNucleusIdentifier");
    }
  }

  function processPhysicsCollisionEvents(collisionEventPayloadObject) {
    let collidingFixturePrimaryElement = collisionEventPayloadObject.getFixtureA();
    let collidingFixtureSecondaryElement = collisionEventPayloadObject.getFixtureB();
    let physicsRigidBodyPrimaryElement = collidingFixturePrimaryElement.getBody();
    let physicsRigidBodySecondaryElement = collidingFixtureSecondaryElement.getBody();

    let physicsCustomMetadataPrimary = physicsRigidBodyPrimaryElement.getUserData();
    let physicsCustomMetadataSecondary = physicsRigidBodySecondaryElement.getUserData();

    let instantaneousVelocityPrimary = physicsRigidBodyPrimaryElement.getLinearVelocity();
    let instantaneousVelocitySecondary = physicsRigidBodySecondaryElement.getLinearVelocity();
    let computedCollisionVelocityMagnitude = Math.max(instantaneousVelocityPrimary.length(), instantaneousVelocitySecondary.length());

    if (!physicsCustomMetadataPrimary && physicsCustomMetadataSecondary) {
      evaluateAcousticKineticImpact(physicsCustomMetadataSecondary, computedCollisionVelocityMagnitude);
    } else if (physicsCustomMetadataPrimary && !physicsCustomMetadataSecondary) {
      evaluateAcousticKineticImpact(physicsCustomMetadataPrimary, computedCollisionVelocityMagnitude);
    } else if (physicsCustomMetadataPrimary && physicsCustomMetadataSecondary) {
      let isPrimaryNeutron = physicsCustomMetadataPrimary.particleClassificationIdentifier === "freeNeutronIdentifier";
      let isSecondaryNucleus = physicsCustomMetadataSecondary.particleClassificationIdentifier === "heavyUraniumNucleusIdentifier";
      let isSecondaryNeutron = physicsCustomMetadataSecondary.particleClassificationIdentifier === "freeNeutronIdentifier";
      let isPrimaryNucleus = physicsCustomMetadataPrimary.particleClassificationIdentifier === "heavyUraniumNucleusIdentifier";

      if (isPrimaryNeutron && isSecondaryNucleus && !physicsCustomMetadataSecondary.isUndergoingExcitationDeformation) {
        triggerNucleusExcitationSequence(physicsCustomMetadataSecondary);
        if (!scheduledRigidBodyAnnihilationQueue.includes(physicsRigidBodyPrimaryElement)) {
          scheduledRigidBodyAnnihilationQueue.push(physicsRigidBodyPrimaryElement);
        }
      } else if (isSecondaryNeutron && isPrimaryNucleus && !physicsCustomMetadataPrimary.isUndergoingExcitationDeformation) {
        triggerNucleusExcitationSequence(physicsCustomMetadataPrimary);
        if (!scheduledRigidBodyAnnihilationQueue.includes(physicsRigidBodySecondaryElement)) {
          scheduledRigidBodyAnnihilationQueue.push(physicsRigidBodySecondaryElement);
        }
      } else {
        evaluateAcousticKineticImpact(physicsCustomMetadataPrimary, computedCollisionVelocityMagnitude);
      }
    }
  }

  simulationGraphicsContext.draw = function() {
    simulationGraphicsContext.background(252, 246, 235);

    let currentSimulationTimeMilliseconds = simulationGraphicsContext.millis();

    for (let particleLifecycleIterator = 0; particleLifecycleIterator < activeSubatomicParticlesRegistry.length; particleLifecycleIterator++) {
      let currentlyEvaluatedParticleEntity = activeSubatomicParticlesRegistry[particleLifecycleIterator];
      let particleMetadataReference = currentlyEvaluatedParticleEntity.rigidBodyEngineReferencePointer.getUserData();

      if (particleMetadataReference.particleClassificationIdentifier === "heavyUraniumNucleusIdentifier" && particleMetadataReference.isUndergoingExcitationDeformation) {
        let elapsedDeformationTimeDuration = currentSimulationTimeMilliseconds - particleMetadataReference.excitationInitiationTimestampMilliseconds;

        if (elapsedDeformationTimeDuration > 800) {
          if (!scheduledRigidBodyAnnihilationQueue.includes(currentlyEvaluatedParticleEntity.rigidBodyEngineReferencePointer)) {
            scheduledRigidBodyAnnihilationQueue.push(currentlyEvaluatedParticleEntity.rigidBodyEngineReferencePointer);

            let nucleusSpatialPositionVector = currentlyEvaluatedParticleEntity.rigidBodyEngineReferencePointer.getPosition();
            scheduledFissionEventSpawningQueue.push({
              fissionOriginCoordinateX: nucleusSpatialPositionVector.x * spatialScalePixelsPerMeterRatio,
              fissionOriginCoordinateY: nucleusSpatialPositionVector.y * spatialScalePixelsPerMeterRatio
            });
          }
        }
      }
    }

    quantumFissionPhysicsEngine.step(1 / 60);

    while (scheduledRigidBodyAnnihilationQueue.length > 0) {
      let pendingAnnihilationTargetRigidBody = scheduledRigidBodyAnnihilationQueue.pop();
      quantumFissionPhysicsEngine.destroyBody(pendingAnnihilationTargetRigidBody);
      activeSubatomicParticlesRegistry = activeSubatomicParticlesRegistry.filter(
        particleEntityElement => particleEntityElement.rigidBodyEngineReferencePointer !== pendingAnnihilationTargetRigidBody
      );
    }

    while (scheduledFissionEventSpawningQueue.length > 0) {
      let pendingFissionExecutionData = scheduledFissionEventSpawningQueue.pop();
      executeNuclearSplittingEventMechanics(pendingFissionExecutionData.fissionOriginCoordinateX, pendingFissionExecutionData.fissionOriginCoordinateY);
    }

    simulationGraphicsContext.blendMode(simulationGraphicsContext.MULTIPLY);
    simulationGraphicsContext.noStroke();

    for (let rippleWaveIteratorIndex = ephemeralKineticRippleWavesArray.length - 1; rippleWaveIteratorIndex >= 0; rippleWaveIteratorIndex--) {
      let currentlyEvaluatedRippleWave = ephemeralKineticRippleWavesArray[rippleWaveIteratorIndex];
      let timeSinceRippleCreationMilliseconds = currentSimulationTimeMilliseconds - currentlyEvaluatedRippleWave.creationTimestampMilliseconds;

      if (timeSinceRippleCreationMilliseconds > 1500) {
        ephemeralKineticRippleWavesArray.splice(rippleWaveIteratorIndex, 1);
        continue;
      }

      let safeRippleProgressRatio = Math.max(0.001, Math.min(1.0, timeSinceRippleCreationMilliseconds / 1500.0));
      let calculatedExpandingRadiusPixels = Math.max(0.001, 10.0 + (240.0 - 10.0) * Math.pow(safeRippleProgressRatio, 0.4));
      let calculatedFadingAlphaValue = Math.max(0.0, 80.0 - (80.0 * safeRippleProgressRatio));

      simulationGraphicsContext.push();
      simulationGraphicsContext.noStroke();
      simulationGraphicsContext.blendMode(simulationGraphicsContext.OVERLAY);

      let rippleGradientObject = simulationGraphicsContext.drawingContext.createRadialGradient(
        currentlyEvaluatedRippleWave.originCoordinateX, currentlyEvaluatedRippleWave.originCoordinateY, calculatedExpandingRadiusPixels * 0.4,
        currentlyEvaluatedRippleWave.originCoordinateX, currentlyEvaluatedRippleWave.originCoordinateY, calculatedExpandingRadiusPixels
      );

      rippleGradientObject.addColorStop(0, `rgba(255, 255, 255, 0)`);
      rippleGradientObject.addColorStop(0.7, `rgba(255, 255, 255, ${calculatedFadingAlphaValue / 255.0})`);
      rippleGradientObject.addColorStop(1, `rgba(255, 255, 255, 0)`);

      simulationGraphicsContext.drawingContext.fillStyle = rippleGradientObject;
      simulationGraphicsContext.circle(currentlyEvaluatedRippleWave.originCoordinateX, currentlyEvaluatedRippleWave.originCoordinateY, calculatedExpandingRadiusPixels * 2.0);
      simulationGraphicsContext.pop();
    }

    for (let entityRenderingIterator = 0; entityRenderingIterator < activeSubatomicParticlesRegistry.length; entityRenderingIterator++) {
      let renderedParticleEntityObject = activeSubatomicParticlesRegistry[entityRenderingIterator];
      let spatialPositionCoordinatesVectorMetersScale = renderedParticleEntityObject.rigidBodyEngineReferencePointer.getPosition();
      let particleMetadataRenderingReference = renderedParticleEntityObject.rigidBodyEngineReferencePointer.getUserData();

      let basePhysicalRadiusDimensionPixelsScale = renderedParticleEntityObject.geometricRadiusDimensionPixelsValue;
      let renderedPixelPositionXCoordinate = spatialPositionCoordinatesVectorMetersScale.x * spatialScalePixelsPerMeterRatio;
      let renderedPixelPositionYCoordinate = spatialPositionCoordinatesVectorMetersScale.y * spatialScalePixelsPerMeterRatio;

      let dynamicDeformationStretchMultiplierX = 1.0;
      let dynamicDeformationStretchMultiplierY = 1.0;

      let activeColorComponentRed = renderedParticleEntityObject.assignedColorComponentsArray[0];
      let activeColorComponentGreen = renderedParticleEntityObject.assignedColorComponentsArray[1];
      let activeColorComponentBlue = renderedParticleEntityObject.assignedColorComponentsArray[2];
      let activeColorComponentAlpha = renderedParticleEntityObject.assignedColorComponentsArray[3];

      if (particleMetadataRenderingReference.particleClassificationIdentifier === "heavyUraniumNucleusIdentifier" && particleMetadataRenderingReference.isUndergoingExcitationDeformation) {
        let elapsedDeformationTimeRendering = currentSimulationTimeMilliseconds - particleMetadataRenderingReference.excitationInitiationTimestampMilliseconds;
        let safeDeformationProgressRatio = Math.max(0.001, Math.min(1.0, elapsedDeformationTimeRendering / 800.0));
        let slowPulsingPhaseOscillator = Math.sin(safeDeformationProgressRatio * mathematicalPiValue * 6.0);

        dynamicDeformationStretchMultiplierX = 1.0 + slowPulsingPhaseOscillator * 0.25;
        dynamicDeformationStretchMultiplierY = 1.0 - slowPulsingPhaseOscillator * 0.15;

        activeColorComponentRed = uraniumNucleusColorComponents[0] + (excitedNucleusColorComponents[0] - uraniumNucleusColorComponents[0]) * safeDeformationProgressRatio;
        activeColorComponentGreen = uraniumNucleusColorComponents[1] + (excitedNucleusColorComponents[1] - uraniumNucleusColorComponents[1]) * safeDeformationProgressRatio;
        activeColorComponentBlue = uraniumNucleusColorComponents[2] + (excitedNucleusColorComponents[2] - uraniumNucleusColorComponents[2]) * safeDeformationProgressRatio;
        activeColorComponentAlpha = uraniumNucleusColorComponents[3] + (excitedNucleusColorComponents[3] - uraniumNucleusColorComponents[3]) * safeDeformationProgressRatio;
      }

      simulationGraphicsContext.push();
      simulationGraphicsContext.translate(renderedPixelPositionXCoordinate, renderedPixelPositionYCoordinate);
      simulationGraphicsContext.rotate(renderedParticleEntityObject.rigidBodyEngineReferencePointer.getAngle());
      simulationGraphicsContext.scale(dynamicDeformationStretchMultiplierX, dynamicDeformationStretchMultiplierY);

      simulationGraphicsContext.fill(activeColorComponentRed, activeColorComponentGreen, activeColorComponentBlue, activeColorComponentAlpha * 0.15);
      simulationGraphicsContext.ellipse(renderedParticleEntityObject.inkMisregistrationOffsetVectorXValue, renderedParticleEntityObject.inkMisregistrationOffsetVectorYValue, basePhysicalRadiusDimensionPixelsScale * 2.8, basePhysicalRadiusDimensionPixelsScale * 2.8);

      let concentricShadingStepsCount = 6;
      for (let shadingLayerIteratorIndex = 0; shadingLayerIteratorIndex < concentricShadingStepsCount; shadingLayerIteratorIndex++) {
        let normalizedShadingProgress = shadingLayerIteratorIndex / (concentricShadingStepsCount - 1);
        let calculatedRadiusForCurrentShadingLayer = Math.max(0.001, basePhysicalRadiusDimensionPixelsScale * 2.2 - (basePhysicalRadiusDimensionPixelsScale * 2.2 - basePhysicalRadiusDimensionPixelsScale * 0.3) * normalizedShadingProgress);
        let calculatedAlphaForCurrentShadingLayer = Math.max(0.0, activeColorComponentAlpha * 0.15 + (activeColorComponentAlpha - activeColorComponentAlpha * 0.15) * normalizedShadingProgress);

        simulationGraphicsContext.fill(activeColorComponentRed, activeColorComponentGreen, activeColorComponentBlue, calculatedAlphaForCurrentShadingLayer);
        simulationGraphicsContext.ellipse(0, 0, calculatedRadiusForCurrentShadingLayer, calculatedRadiusForCurrentShadingLayer);
      }

      simulationGraphicsContext.pop();
    }

    simulationGraphicsContext.blendMode(simulationGraphicsContext.DARKEST);
    simulationGraphicsContext.image(tactilePaperGrainTextureBuffer, 0, 0);
    simulationGraphicsContext.blendMode(simulationGraphicsContext.BLEND);
  };

  function applySelectedHarmonicScaleByName(targetScaleNameString) {
    currentActiveScaleName = targetScaleNameString;
    let retrievedScaleDefinitionObject = globalHarmonicScalesDictionary[currentActiveScaleName];

    activeMelodicPitchesLow = retrievedScaleDefinitionObject.low;
    activeMelodicPitchesMid = retrievedScaleDefinitionObject.mid;
    activeMelodicPitchesHigh = retrievedScaleDefinitionObject.high;
  }

  function triggerNucleusExcitationSequence(particleMetadataEntity) {
    particleMetadataEntity.isUndergoingExcitationDeformation = true;
    particleMetadataEntity.excitationInitiationTimestampMilliseconds = simulationGraphicsContext.millis();

    if (Tone.context.state === 'running') {
      let currentTimeVerification = simulationGraphicsContext.millis();
      if (currentTimeVerification - globalLastOboeTriggerTimestamp > 250) {
        globalLastOboeTriggerTimestamp = currentTimeVerification;
        let selectedExcitationPadPitch = activeMelodicPitchesLow[Math.floor(simulationGraphicsContext.random(activeMelodicPitchesLow.length))];
        organicOboeWindInstrument.triggerAttackRelease(selectedExcitationPadPitch, 1.0, undefined, 0.6);
      }
    }
  }

  function evaluateAcousticKineticImpact(particleMetadataEntity, velocityMagnitudeValue) {
    let acousticTriggerThresholdVelocity = 3.0;

    if (velocityMagnitudeValue > acousticTriggerThresholdVelocity && Tone.context.state === 'running') {
      let currentTimeVerification = simulationGraphicsContext.millis();
      let mappedAcousticAmplitudeMultiplier = Math.min((velocityMagnitudeValue - acousticTriggerThresholdVelocity) * 0.015, 0.5);

      if (particleMetadataEntity.particleClassificationIdentifier === "freeNeutronIdentifier") {
        if (currentTimeVerification - globalLastKotoTriggerTimestamp > 80) {
          globalLastKotoTriggerTimestamp = currentTimeVerification;
          let randomlySelectedHighGlassPitch = activeMelodicPitchesHigh[Math.floor(simulationGraphicsContext.random(activeMelodicPitchesHigh.length))];
          organicKotoPluckInstrument.triggerAttackRelease(randomlySelectedHighGlassPitch, "16n", undefined, mappedAcousticAmplitudeMultiplier);
        }
      } else if (particleMetadataEntity.particleClassificationIdentifier === "fissionFragmentIdentifier") {
        if (currentTimeVerification - globalLastViolaTriggerTimestamp > 120) {
          globalLastViolaTriggerTimestamp = currentTimeVerification;
          let randomlySelectedWarmMidPitch = activeMelodicPitchesMid[Math.floor(simulationGraphicsContext.random(activeMelodicPitchesMid.length))];
          organicViolaBowedInstrument.triggerAttackRelease(randomlySelectedWarmMidPitch, "8n", undefined, mappedAcousticAmplitudeMultiplier * 0.8);
        }
      }
    }
  }

  function executeNuclearSplittingEventMechanics(originFissionCoordinateX, originFissionCoordinateY) {
    ephemeralKineticRippleWavesArray.push({
      originCoordinateX: originFissionCoordinateX,
      originCoordinateY: originFissionCoordinateY,
      creationTimestampMilliseconds: simulationGraphicsContext.millis()
    });

    if (Tone.context.state === 'running') {
      let currentTimeVerification = simulationGraphicsContext.millis();
      if (currentTimeVerification - globalLastViolaTriggerTimestamp > 100) {
        globalLastViolaTriggerTimestamp = currentTimeVerification;
        let harmonyRootPitchSelection = activeMelodicPitchesMid[Math.floor(simulationGraphicsContext.random(activeMelodicPitchesMid.length))];
        let harmonyThirdPitchSelection = activeMelodicPitchesHigh[Math.floor(simulationGraphicsContext.random(activeMelodicPitchesHigh.length))];
        organicViolaBowedInstrument.triggerAttackRelease([harmonyRootPitchSelection, harmonyThirdPitchSelection], "2n", undefined, 0.8);
      }
    }

    let calculatedSplittingAxisAngleRadians = simulationGraphicsContext.random(mathematicalPiValue * 2);
    let calculatedOppositeSplittingAxisAngleRadians = calculatedSplittingAxisAngleRadians + mathematicalPiValue;

    instantiateSubatomicParticleEntity(originFissionCoordinateX, originFissionCoordinateY, "fissionFragmentIdentifier", calculatedSplittingAxisAngleRadians);
    instantiateSubatomicParticleEntity(originFissionCoordinateX, originFissionCoordinateY, "fissionFragmentIdentifier", calculatedOppositeSplittingAxisAngleRadians);

    let calculatedNeutronYieldCount = Math.floor(simulationGraphicsContext.random(2, 4));
    for (let emittedNeutronIterator = 0; emittedNeutronIterator < calculatedNeutronYieldCount; emittedNeutronIterator++) {
      let randomizedNeutronEmissionAngleRadians = simulationGraphicsContext.random(mathematicalPiValue * 2);
      instantiateSubatomicParticleEntity(originFissionCoordinateX, originFissionCoordinateY, "freeNeutronIdentifier", randomizedNeutronEmissionAngleRadians);
    }
  }

  function instantiateSubatomicParticleEntity(originSpawnCoordinatePixelsXAxis, originSpawnCoordinatePixelsYAxis, designatedParticleTypeIdentifier, optionalPropulsionAngleRadians = 0) {
    let specificGeometricRadiusPixelsSizeValue;
    let specificLinearDampingConstraintValue;
    let specificRestitutionConstraintValue;
    let assignedVisualColorComponentsArrayReference;

    if (designatedParticleTypeIdentifier === "heavyUraniumNucleusIdentifier") {
      specificGeometricRadiusPixelsSizeValue = 26;
      specificLinearDampingConstraintValue = 5.0;
      specificRestitutionConstraintValue = 0.9;
      assignedVisualColorComponentsArrayReference = uraniumNucleusColorComponents;
    } else if (designatedParticleTypeIdentifier === "fissionFragmentIdentifier") {
      specificGeometricRadiusPixelsSizeValue = 16;
      specificLinearDampingConstraintValue = 1.0;
      specificRestitutionConstraintValue = 0.95;
      assignedVisualColorComponentsArrayReference = fissionFragmentColorComponents;
    } else if (designatedParticleTypeIdentifier === "freeNeutronIdentifier") {
      specificGeometricRadiusPixelsSizeValue = 7;
      specificLinearDampingConstraintValue = 0.0;
      specificRestitutionConstraintValue = 1.0;
      assignedVisualColorComponentsArrayReference = freeNeutronColorComponents;
    }

    let geometricRadiusMetersSizeValue = specificGeometricRadiusPixelsSizeValue * spatialScaleMetersPerPixelRatio;

    let entityCustomMetadataStorageStateObject = { 
      particleClassificationIdentifier: designatedParticleTypeIdentifier,
      isUndergoingExcitationDeformation: false,
      excitationInitiationTimestampMilliseconds: 0
    };

    let physicsBodyCreationDefinitionPropertiesMap = {
      type: 'dynamic',
      position: planck.Vec2(originSpawnCoordinatePixelsXAxis * spatialScaleMetersPerPixelRatio, originSpawnCoordinatePixelsYAxis * spatialScaleMetersPerPixelRatio),
      userData: entityCustomMetadataStorageStateObject,
      linearDamping: specificLinearDampingConstraintValue,
      angularDamping: 0.5,
      bullet: designatedParticleTypeIdentifier === "freeNeutronIdentifier"
    };

    let newlyInitializedRigidBodyInstancePointer = quantumFissionPhysicsEngine.createBody(physicsBodyCreationDefinitionPropertiesMap);

    let dynamicFixtureMaterialDefinitionPropertiesMap = {
      density: designatedParticleTypeIdentifier === "heavyUraniumNucleusIdentifier" ? 15.0 : 2.0,
      friction: 0.0,
      restitution: specificRestitutionConstraintValue
    };

    newlyInitializedRigidBodyInstancePointer.createFixture(planck.Circle(geometricRadiusMetersSizeValue), dynamicFixtureMaterialDefinitionPropertiesMap);

    if (designatedParticleTypeIdentifier === "fissionFragmentIdentifier") {
      let randomizedFragmentPropulsionVelocityMagnitude = simulationGraphicsContext.random(8, 18);
      let explosivePropulsionVelocityVectorMetersScale = planck.Vec2(Math.cos(optionalPropulsionAngleRadians) * randomizedFragmentPropulsionVelocityMagnitude, Math.sin(optionalPropulsionAngleRadians) * randomizedFragmentPropulsionVelocityMagnitude);
      newlyInitializedRigidBodyInstancePointer.setLinearVelocity(explosivePropulsionVelocityVectorMetersScale);
    } else if (designatedParticleTypeIdentifier === "freeNeutronIdentifier") {
      let randomizedNeutronPropulsionVelocityMagnitude = simulationGraphicsContext.random(30, 45);
      let explosivePropulsionVelocityVectorMetersScale = planck.Vec2(Math.cos(optionalPropulsionAngleRadians) * randomizedNeutronPropulsionVelocityMagnitude, Math.sin(optionalPropulsionAngleRadians) * randomizedNeutronPropulsionVelocityMagnitude);
      newlyInitializedRigidBodyInstancePointer.setLinearVelocity(explosivePropulsionVelocityVectorMetersScale);
    }

    activeSubatomicParticlesRegistry.push({
      rigidBodyEngineReferencePointer: newlyInitializedRigidBodyInstancePointer,
      geometricRadiusDimensionPixelsValue: specificGeometricRadiusPixelsSizeValue,
      assignedColorComponentsArray: assignedVisualColorComponentsArrayReference,
      inkMisregistrationOffsetVectorXValue: simulationGraphicsContext.random(-6, 6),
      inkMisregistrationOffsetVectorYValue: simulationGraphicsContext.random(-6, 6)
    });
  }

  simulationGraphicsContext.mousePressed = async function(eventReferenceData) {
    if (eventReferenceData.target.tagName === 'SELECT' || eventReferenceData.target.tagName === 'BUTTON') {
      return;
    }
    await Tone.start();

    let canvasElementBoundingRectangle = simulationGraphicsContext.canvas.getBoundingClientRect();
    if (simulationGraphicsContext.mouseX >= 0 && simulationGraphicsContext.mouseX <= canvasElementBoundingRectangle.width &&
        simulationGraphicsContext.mouseY >= 0 && simulationGraphicsContext.mouseY <= canvasElementBoundingRectangle.height) {
      let initialTriggerNeutronAngleRadians = Math.atan2(simulationGraphicsContext.mouseY - simulationCanvasViewportHeight * 0.5, simulationGraphicsContext.mouseX - simulationCanvasViewportWidth * 0.5);
      instantiateSubatomicParticleEntity(simulationGraphicsContext.mouseX, simulationGraphicsContext.mouseY, "freeNeutronIdentifier", initialTriggerNeutronAngleRadians);
    }
  };
});

